PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, role TEXT NOT NULL DEFAULT 'brand', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS creators (id INTEGER PRIMARY KEY, name TEXT NOT NULL, handle TEXT UNIQUE NOT NULL, platform TEXT DEFAULT 'Instagram', followers INTEGER NOT NULL DEFAULT 0, engagement REAL NOT NULL DEFAULT 0, niche TEXT DEFAULT '', city TEXT DEFAULT '', trust_score INTEGER DEFAULT 70, completed_collaborations INTEGER DEFAULT 0, successful_posts INTEGER DEFAULT 0, ghosted_campaigns INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, category TEXT DEFAULT '', price REAL NOT NULL DEFAULT 0, stock INTEGER NOT NULL DEFAULT 0, description TEXT DEFAULT '', reserved_units INTEGER DEFAULT 0, shipped_units INTEGER DEFAULT 0, unit_cost REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS campaigns (id INTEGER PRIMARY KEY, brand_id INTEGER REFERENCES users(id), title TEXT NOT NULL, product_id INTEGER REFERENCES products(id), niche TEXT DEFAULT '', city TEXT DEFAULT '', budget REAL DEFAULT 0, status TEXT DEFAULT 'active', created_at TEXT DEFAULT CURRENT_TIMESTAMP, description TEXT DEFAULT '', minimum_followers INTEGER DEFAULT 0, minimum_engagement REAL DEFAULT 0, posting_deadline_days INTEGER DEFAULT 7, target_platform TEXT DEFAULT 'Instagram', deliverables TEXT DEFAULT '1 social post');
CREATE TABLE IF NOT EXISTS collaborations (id INTEGER PRIMARY KEY, campaign_id INTEGER REFERENCES campaigns(id), creator_id INTEGER REFERENCES creators(id), status TEXT DEFAULT 'invited', agreed_value REAL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, claimed_at TEXT, shipped_at TEXT, delivered_at TEXT, deadline TEXT, completed_at TEXT);
CREATE TABLE IF NOT EXISTS shipments (id INTEGER PRIMARY KEY, collaboration_id INTEGER REFERENCES collaborations(id), provider TEXT DEFAULT 'Mock', tracking_code TEXT, stage TEXT DEFAULT 'order_placed', updated_at TEXT DEFAULT CURRENT_TIMESTAMP, dispatched_at TEXT, delivered_at TEXT);
CREATE TABLE IF NOT EXISTS proofs (id INTEGER PRIMARY KEY, collaboration_id INTEGER REFERENCES collaborations(id), url TEXT NOT NULL UNIQUE, caption TEXT DEFAULT '', verified INTEGER DEFAULT 0, submitted_at TEXT DEFAULT CURRENT_TIMESTAMP, verified_by INTEGER REFERENCES users(id), verified_at TEXT);
CREATE TABLE IF NOT EXISTS trust_events (id INTEGER PRIMARY KEY, creator_id INTEGER REFERENCES creators(id), event_type TEXT NOT NULL, score_change INTEGER NOT NULL, reason TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_creators_niche ON creators(niche);
CREATE INDEX IF NOT EXISTS idx_campaign_status ON campaigns(status);
CREATE INDEX IF NOT EXISTS idx_collab_status ON collaborations(status);
CREATE INDEX IF NOT EXISTS idx_shipments_collab ON shipments(collaboration_id);
